import torch


def gen_inputs(ctx, device):
    x_shape = ctx["x__shape"]
    x_dtype = getattr(torch, ctx["x__dtype"])
    y_shape = ctx["y__shape"]
    y_dtype = getattr(torch, ctx["y__dtype"])
    x = torch.randint(1, 100, x_shape, dtype=x_dtype, device="cpu").to(device)
    y = torch.randint(1, 100, y_shape, dtype=y_dtype, device="cpu").to(device)
    return {"x": x, "y": y}


def run(x, y):
    return torch.lcm(x, y)
